changeSet.sql:
CREATE TABLE public.track_energy_recalculation (
    track_id bigint PRIMARY KEY REFERENCES public.gps_track(id) ON DELETE CASCADE,
    generation bigint NOT NULL,
    requested_at timestamp with time zone NOT NULL,
    next_attempt_at timestamp with time zone NOT NULL,
    last_error varchar(100)
);
CREATE INDEX idx_track_energy_recalculation_due
    ON public.track_energy_recalculation (next_attempt_at, track_id);
